mapper.select:
select ar.id, ar.recommend_type as recommendType, ar.book_id as bookId, bi.cover_url as coverUrl, bi.book_name as bookName, ai.author_name as authorName, ar.start_time as startTime, ar.end_time as endTime, ar.recommend_status as recommendStatus from admin_recommend ar inner join book_info bi on ar.book_id = bi.id inner join author_info ai on bi.author_id = ai.id
and ar.recommend_type = #{recommendType}
order by ar.create_time
